import React from "react";

const tutors = [
  {
    name: "Ms. Chen",
    subject: "Chemistry",
    bio: "Specializes in chemical reactions, atoms, and making chemistry feel intuitive.",
  },
  {
    name: "Mr. Patel",
    subject: "Physics",
    bio: "Explains forces and motion using real-life examples and hands-on thinking.",
  },
  {
    name: "Sarah (Peer Tutor)",
    subject: "Biology",
    bio: "Helps students understand cells, genetics, and biology foundations.",
  },
];

function AboutTutors() {
  return (
    <section className="page fade-in">
      <h1 className="slide-up">Meet the Team</h1>
      <p className="slide-up" style={{ maxWidth: "700px" }}>
        Our tutors are passionate about helping students understand science in a clear,
        friendly, and supportive way.
      </p>

      <div className="tutor-grid slide-up" style={{ marginTop: "2rem" }}>
        {tutors.map((tutor, i) => (
          <div key={i} className="card">
            <h2>{tutor.name}</h2>
            <p><strong>Subject:</strong> {tutor.subject}</p>
            <p>{tutor.bio}</p>
          </div>
        ))}
      </div>
    </section>
  );
}

export default AboutTutors;
